}","newString":"export async function runSchedule(graph, { limit, run }) {
  if (!Number.isInteger(limit) || limit < 1) throw new TypeError('limit must be a positive integer');
  const byId = new Map();
  for (const node of graph) {
    if (byId.has(node.id)) throw new Error(`Duplicate node: ${node.id}`);
    byId.set(node.id, node);
  }
  for (const node of graph) for (const dependency of node.deps) {
    if (!byId.has(dependency)) throw new Error(`Missing dependency: ${dependency}`);
  }
  const indegree = new Map(graph.map(node => [node.id, node.deps.length]));
  const queue = graph.filter(node => indegree.get(node.id) === 0).map(node => node.id);
  let seen = 0;
  for (let cursor = 0; cursor < queue.length; cursor += 1) {
    const id = queue[cursor];
    seen += 1;
    for (const node of graph) if (node.deps.includes(id)) {
      const next = indegree.get(node.id) - 1;
      indegree.set(node.id, next);
      if (next === 0) queue.push(node.id);
    }
  }
  if (seen !== graph.length) throw new Error('Dependency cycle detected');
  const results = new Array(graph.length);
  const completed = new Set();
  const remaining = new Set(graph.map(node => node.id));
  return await new Promise((resolve, reject) => {
    let active = 0;
    let settled = false;
    const launch = () => {
      if (settled) return;
      if (completed.size === graph.length) { settled = true; resolve(results); return; }
      for (let index = 0; index < graph.length && active < limit; index += 1) {
        const node = graph[index];
        if (!remaining.has(node.id) || !node.deps.every(id => completed.has(id))) continue;
        remaining.delete(node.id);
        active += 1;
        Promise.resolve().then(() => run(node)).then(value => {
          if (settled) return;
          results[index] = value;
          completed.add(node.id);
          active -= 1;
          launch();
        }, error => { settled = true; reject(error); });
      }
    };
    launch();
  });
}"}

